// Decrypts pages generated by bin/protect-page.mjs (AES-GCM + PBKDF2-SHA256).
(() => {
  const MARKED_SRC = "https://cdn.jsdelivr.net/npm/marked@18.0.14/lib/marked.umd.js";
  const MARKED_SRI = "sha384-2vpGtuKqJvFlwJqYnf/wUMuzUfhUnYBt9oay0e2yaFcq0Dh6/aEbQ8YAOeKGzlYo";
  const STORAGE_KEY = "protected-page-password";

  const fromBase64 = (value) => Uint8Array.from(atob(value), (c) => c.charCodeAt(0));

  let markedPromise;
  function loadMarked() {
    if (window.marked) return Promise.resolve(window.marked);
    markedPromise ||= new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = MARKED_SRC;
      script.integrity = MARKED_SRI;
      script.crossOrigin = "anonymous";
      script.onload = () => resolve(window.marked);
      script.onerror = () => reject(new Error("Failed to load the Markdown renderer."));
      document.head.appendChild(script);
    });
    return markedPromise;
  }

  async function decrypt(encoded, password) {
    const payload = JSON.parse(new TextDecoder().decode(fromBase64(encoded)));
    const baseKey = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveKey"]);
    const key = await crypto.subtle.deriveKey(
      { name: "PBKDF2", salt: fromBase64(payload.salt), iterations: payload.iter, hash: "SHA-256" },
      baseKey,
      { name: "AES-GCM", length: 256 },
      false,
      ["decrypt"]
    );
    const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: fromBase64(payload.iv) }, key, fromBase64(payload.ct));
    return new TextDecoder().decode(plain);
  }

  function readStored() {
    try {
      return sessionStorage.getItem(STORAGE_KEY);
    } catch {
      return null;
    }
  }

  function store(password) {
    try {
      sessionStorage.setItem(STORAGE_KEY, password);
    } catch {
      /* storage unavailable; the user will be asked again next time */
    }
  }

  async function unlock(container, password) {
    const markdown = await decrypt(container.dataset.payload, password);
    const marked = await loadMarked();
    container.innerHTML = marked.parse(markdown);
    store(password);
  }

  function renderForm(container) {
    container.innerHTML = `
      <form class="protected-page-form" style="max-width: 22rem; margin: 2rem auto; text-align: center;">
        <p><i class="fa-solid fa-lock"></i> This page is password protected.</p>
        <input type="password" autocomplete="current-password" aria-label="Password" placeholder="Password" required
          style="width: 100%; padding: 0.5rem; margin-bottom: 0.5rem; border: 1px solid var(--global-divider-color);
                 border-radius: 0.25rem; background: var(--global-bg-color); color: var(--global-text-color);">
        <button type="submit"
          style="width: 100%; padding: 0.5rem; border: none; border-radius: 0.25rem;
                 background: var(--global-theme-color); color: #fff; cursor: pointer;">Unlock</button>
        <p class="protected-page-error" role="alert" style="color: #d33; min-height: 1.5em; margin-top: 0.5rem;"></p>
      </form>`;
    const form = container.querySelector("form");
    const input = form.querySelector("input");
    const error = form.querySelector(".protected-page-error");
    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      error.textContent = "";
      form.querySelector("button").disabled = true;
      try {
        await unlock(container, input.value);
      } catch (e) {
        error.textContent = e instanceof DOMException ? "Incorrect password." : e.message;
        form.querySelector("button").disabled = false;
        input.select();
      }
    });
    input.focus();
  }

  function init() {
    document.querySelectorAll(".protected-page[data-payload]").forEach((container) => {
      const stored = readStored();
      if (stored) {
        unlock(container, stored).catch(() => renderForm(container));
      } else {
        renderForm(container);
      }
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
